from invoice_tools.parser import parse
bad = 'invoice,customer,description,quantity,unit_price,tax_rate\nINV-1,A,W,1,2.00,0.2\nINV-2,B,W,many,2.00,0.2\n'
try:
    parse(bad)
except ValueError as e:
    assert '3' in str(e), e
else:
    raise AssertionError('no ValueError')
assert len(parse('invoice,customer,description,quantity,unit_price,tax_rate\nINV-1,A,W,1,2.00,0.2\n')) == 1
